"""Original low-detail aquatic silhouettes; no external assets."""
from pathlib import Path
from PIL import Image,ImageDraw
OUT=Path(__file__).resolve().parents[1]/'client/Assets/Wildfolk/Art'
S=4
def icon(name,paint):
 im=Image.new('RGBA',(160*S,128*S));d=ImageDraw.Draw(im)
 class Pen:
  def poly(self,p,c):d.polygon([(int(x*S),int(y*S)) for x,y in p],fill=c)
  def oval(self,p,c):d.ellipse(tuple(int(v*S) for v in p),fill=c)
  def line(self,p,c,w=2):d.line([(int(x*S),int(y*S)) for x,y in p],fill=c,width=w*S,joint='curve')
 p=Pen();paint(p);im.resize((160,128),Image.Resampling.LANCZOS).save(OUT/(name+'.png'))
def carp(p):
 p.poly([(47,68),(17,41),(23,75),(14,92),(52,81)],'#665e41');p.poly([(64,45),(80,22),(104,40),(126,49)],'#756849');p.oval((38,38,148,98),'#343f36');p.oval((41,38,146,93),'#a79c6e');p.oval((66,44,140,80),'#bcb589');p.poly([(85,82),(64,104),(107,92)],'#77694b');p.line([(119,49),(114,63),(119,82)],'#635f48',3);p.oval((132,53,139,60),'#293331');p.line([(57,56),(75,60),(94,58)],'#8d8b60');p.line([(55,72),(74,77),(95,72)],'#8d8b60')
def perch(p):
 p.poly([(49,70),(16,42),(23,68),(17,91),(55,80)],'#7f7660');p.poly([(52,48),(59,26),(70,37),(79,21),(88,36),(99,28),(106,44)],'#817c55');p.poly([(41,65),(61,43),(100,41),(142,65),(135,87),(78,93),(49,80)],'#3d4b42');p.poly([(44,65),(66,49),(105,48),(140,67),(129,82),(77,88),(51,77)],'#8e9b79');p.poly([(66,51),(72,52),(79,84),(70,84)],'#4c6455');p.poly([(88,48),(96,50),(100,84),(92,87)],'#4c6455');p.poly([(110,51),(116,55),(120,79),(113,84)],'#4c6455');p.poly([(77,86),(67,107),(98,91)],'#967656');p.oval((126,61,134,69),'#243635');p.line([(120,58),(115,71),(119,80)],'#586650')
def mackerel(p):
 p.poly([(52,62),(15,38),(28,66),(15,99),(54,77)],'#44585b');p.poly([(43,63),(81,41),(115,46),(150,67),(126,84),(77,88),(43,76)],'#344d54');p.poly([(45,70),(84,63),(139,65),(148,69),(123,81),(77,84),(47,75)],'#b0b5a3');p.poly([(78,46),(88,26),(108,46)],'#506d71');p.poly([(92,82),(81,103),(115,84)],'#687c76');
 for x in [65,79,93,107]:p.line([(x,51),(x+6,56),(x+4,62)],'#76968d',2)
 p.oval((131,59,138,66),'#1f3439');p.line([(123,54),(118,65),(123,76)],'#5d797b')
def eel(p):
 p.line([(17,42),(22,78),(43,94),(68,91),(85,70),(103,53),(129,54),(143,62)],'#2d3e38',24);p.line([(17,42),(26,77),(46,87),(66,84),(84,64),(104,47),(128,47),(143,57)],'#6f8062',16);p.line([(27,80),(48,96),(70,90),(90,66),(107,55),(130,57)],'#b0a87b',5);p.poly([(111,60),(94,79),(122,66)],'#7e805d');p.oval((133,46,151,66),'#738367');p.oval((141,49,146,54),'#263b33');p.line([(145,62),(154,60)],'#33493c',2)
def portions(p):
 p.poly([(22,36),(130,31),(146,96),(29,103)],'#526a47');p.line([(28,41),(135,93)],'#85946b',3)
 for off in [0,36]:
  p.poly([(37+off,48),(61+off,42),(82+off,85),(58+off,92)],'#715438');p.poly([(40+off,49),(59+off,46),(77+off,83),(59+off,88)],'#c0a06a');p.line([(49+off,56),(64+off,79)],'#8e6c45',3)
 p.line([(32,73),(137,63)],'#c6b68a',4)
for name,paint in [('crucian_carp',carp),('perch',perch),('mackerel',mackerel),('eel',eel),('fish_portions',portions)]:icon(name,paint)
